cd /workspace && grep -rhoE 'from "[^"]+"|from '"'"'[^'"'"']+'"'"'' src/js/index.html 2>/dev/null | head; echo "=== resolve imports in src ==="; python3 - <<'EOF'
import os,re,glob
missing=[]
for root,dirs,files in os.walk('src'):
    for f in files:
        if f.endswith('.js'):
            p=os.path.join(root,f)
            txt=open(p,encoding='utf-8',errors='replace').read()
            for m in re.finditer(r'''(?:from|import)\s+['"]([^'"]+)['"]''',txt):
                imp=m.group(1)
                if imp.startswith('.') or imp.startswith('/'):
                    base=os.path.normpath(os.path.join(root,imp))
                    cands=[base,base+'.js',base+'.json',os.path.join(base,'index.js')]
                    if not any(os.path.exists(c) for c in cands):
                        missing.append((p,imp))
print("missing relative imports:",len(missing))
for x in missing[:40]: print(x)
EOF
